 ____string2Number = function(value, errorMsg) {
  if(typeof value !== 'string'){
    return value;
  }
  if (/^\-?\d+$/.test(value)) {
      return parseInt(value);
  } else if (/^\-?\d+\.\d+$/.test(value)) {
